export const BODY: string = "\n<p>ہر تصویر کے اندر ایک چھپی ہوئی تہہ ہوتی ہے: کیمرے کا نام، لینے کی تاریخ، مقام اور سیٹنگز۔ یہ معلومات میٹا ڈیٹا کہلاتی ہے، اور میٹا ڈیٹا ویور اسے پڑھ کر دکھاتا ہے۔</p>\n<p>میٹا ڈیٹا دیکھنا فوٹوگرافروں کے لیے مفید ہے اور پرائیویسی کے لیے ضروری ہے۔ آپ جان سکتے ہیں کہ تصویر کہاں اور کب لی گئی تھی، اور شیئر کرنے سے پہلے کیا ہٹانا چاہیے۔</p>\n<p>یہ رہنما بتاتا ہے کہ ویور کیا دکھاتا ہے، EXIF فیلڈز کا مطلب کیا ہے، GPS کا خطرہ کیا ہے، اور صاف فائل کی تصدیق کیسے کریں۔ جانچنے کے لیے <a href=\"/ur/tasveer-metadata-dekhein/\">امیج میٹا ڈیٹا ویور</a> کھولیں۔</p>\n<h2 id=\"what-is-image-metadata\">امیج میٹا ڈیٹا کیا ہے؟</h2>\n<p>میٹا ڈیٹا وہ معلومات ہے جو تصویر کے ساتھ فائل میں محفوظ ہوتی ہے، مگر تصویر میں نظر نہیں آتی۔ اس میں کیمرے کا ماڈل، لینس، شٹر رفتار، تاریخ اور مقام شامل ہو سکتے ہیں۔</p>\n<p>میٹا ڈیٹا تصویر بناتے وقت خود بخود لکھا جاتا ہے۔ آپ کو اسے دیکھنے کے لیے خصوصی ٹول چاہیے، کیونکہ عام گیلری صرف تصویر دکھاتی ہے، اس کے پیچھے کی معلومات نہیں۔</p>\n<h2 id=\"what-the-viewer-shows\">ویور آپ کو کیا دکھاتا ہے</h2>\n<p>ویور تصویر کی بنیادی معلومات دکھاتا ہے: ابعاد، فارمیٹ، فائل سائز اور رنگ کی تفصیل۔ پھر وہ EXIF فیلڈز کی فہرست دکھاتا ہے، جیسے کیمرہ، تاریخ اور سیٹنگز۔</p>\n<p>اگر تصویر میں GPS ہو تو ویور مقام کے کوآرڈینیٹس بھی دکھاتا ہے۔ یہ حصہ سب سے اہم ہے، کیونکہ اسی سے پتا چلتا ہے کہ تصویر کہاں لی گئی تھی۔</p>\n<h2 id=\"exif-fields-explained\">EXIF فیلڈز کی وضاحت</h2>\n<p>EXIF کیمرے کی معلومات کا معیار ہے۔ اس میں شٹر رفتار، اپرچر، ISO، فوکل لمبائی اور وائٹ بیلنس جیسے فیلڈز ہوتے ہیں، جو بتاتے ہیں کہ تصویر کن سیٹنگز پر لی گئی تھی۔</p>\n<p>فوٹوگرافر ان فیلڈز سے سیکھتے ہیں کہ اچھی تصویر کیسے بنی۔ مثال کے طور پر، کم ISO اور تیز شٹر والی تصویر صاف ہوتی ہے، جبکہ زیادہ ISO والی میں دانے نظر آتے ہیں۔</p>\n<h2 id=\"gps-and-privacy\">GPS ڈیٹا اور پرائیویسی</h2>\n<p>اگر فون کا مقام آن تھا تو تصویر میں GPS کوآرڈینیٹس محفوظ ہو جاتے ہیں، جو گھر کا درست پتہ بتا سکتے ہیں۔ یہ معلومات شیئر کی گئی تصویر کے ساتھ ہر دیکھنے والے تک پہنچ سکتی ہے۔</p>\n<p>بچوں اور گھر کی تصویریں شیئر کرنے سے پہلے GPS ضرور جانچیں۔ مقام ہٹانا آسان ہے، مگر ایک بار شیئر شدہ تصویر سے مقام ہٹانا ممکن نہیں ہوتا۔</p>\n<h2 id=\"png-and-webp-chunks\">PNG اور WebP تکنیکی ہیڈر</h2>\n<p>PNG اور WebP میں EXIF کے بجائے چنکس ہوتے ہیں، جو رنگ پروفائل، شفافیت اور متن کی معلومات رکھتے ہیں۔ ویور یہ چنکس پڑھ کر بتاتا ہے کہ فائل کے اندر کیا چھپا ہے۔</p>\n<p>یہ تکنیکی تفصیل ڈویلپرز اور ڈیزائنرز کے لیے اہم ہے، کیونکہ غلط رنگ پروفائل تصویر کے رنگ بدل سکتا ہے۔ عام صارف کے لیے صرف یہ جاننا کافی ہے کہ فائل میں اضافی معلومات ہیں یا نہیں۔</p>\n<h2 id=\"how-to-use-the-viewer\">ویور کیسے استعمال کریں</h2>\n<p>تصویر ویور میں ڈالیں اور فیلڈز کی فہرست دیکھیں۔ ہر فیلڈ کے ساتھ اس کی قیمت لکھی ہوتی ہے، اور اہم فیلڈز، جیسے GPS، نمایاں کیے جاتے ہیں۔</p>\n<p>جانچ کے بعد رپورٹ محفوظ کریں یا تصویر صاف کرنے کا فیصلہ کریں۔ ویور کچھ نہیں بدلتا، وہ صرف دکھاتا ہے، اس لیے اسے بے فکر ہو کر استعمال کریں۔</p>\n<h2 id=\"json-export\">JSON رپورٹ نقل کرنا اور برآمد کرنا</h2>\n<p>رپورٹ کو JSON فائل کے طور پر برآمد کیا جا سکتا ہے، جس میں تمام فیلڈز منظم شکل میں ہوتے ہیں۔ یہ ڈویلپرز کے لیے مفید ہے جو میٹا ڈیٹا کو خودکار نظام میں استعمال کرتے ہیں۔</p>\n<p>JSON رپورٹ کو ٹیم کے ساتھ بانٹنا بھی آسان ہے۔ فوٹوگرافر کلائنٹ کو رپورٹ بھیج کر بتا سکتا ہے کہ تصویر کن سیٹنگز پر لی گئی تھی۔</p>\n<h2 id=\"verifying-clean-files\">صاف شدہ فائل کی تصدیق</h2>\n<p>میٹا ڈیٹا صاف کرنے کے بعد فائل کو دوبارہ ویور میں ڈال کر جانچیں۔ صاف فائل میں GPS اور کیمرے کی معلومات نہیں ہونی چاہییں، صرف بنیادی ابعاد اور فارمیٹ رہنے چاہییں۔</p>\n<p>یہ دوسری جانچ بہت اہم ہے، کیونکہ کچھ ٹول میٹا ڈیٹا کا صرف ایک حصہ ہٹاتے ہیں۔ دوبارہ جانچے بغیر شیئر کرنا خطرہ مول لینا ہے۔</p>\n<h2 id=\"when-to-check-metadata\">میٹا ڈیٹا کب جانچیں</h2>\n<p>میٹا ڈیٹا اس وقت جانچیں جب تصویر کسی اجنبی کو بھیجنی ہو، آن لائن بیچنی ہو، یا سوشل میڈیا پر ڈالنی ہو۔ خاص طور پر گھر، بچوں اور دفتر کی تصویروں کی جانچ ضروری ہے۔</p>\n<p>دوسروں سے ملی تصویر بھی جانچیں، کیونکہ اس میں بھیجنے والے کا مقام یا آلہ کی معلومات ہو سکتی ہیں۔ جانچنا چند سیکنڈ کا کام ہے اور پرائیویسی کی بڑی حفاظت ہے۔</p>\n<h2 id=\"viewer-limits\">ویور کیا نہیں کر سکتا</h2>\n<p>ویور تصویر کی صداقت ثابت نہیں کر سکتا اور نہ ہی یہ بتا سکتا ہے کہ تصویر ایڈٹ ہوئی ہے یا نہیں۔ وہ صرف وہی دکھاتا ہے جو فائل میں لکھا ہے، اور لکھی ہوئی معلومات جعلی بھی ہو سکتی ہیں۔</p>\n<p>ویور میٹا ڈیٹا ہٹا بھی نہیں سکتا، وہ صرف دکھاتا ہے۔ ہٹانے کے لیے الگ ٹول چاہیے، اور ہٹانے کے بعد دوبارہ جانچ کے لیے ویور دوبارہ استعمال کریں۔</p>\n<h2 id=\"metadata-on-mobile\">موبائل پر میٹا ڈیٹا جانچنا</h2>\n<p>ویور براؤزر میں چلتا ہے، اس لیے موبائل پر بھی کام کرتا ہے۔ گیلری سے تصویر منتخب کریں اور فیلڈز فوراً دیکھیں، کوئی ایپ انسٹال کرنے کی ضرورت نہیں۔</p>\n<p>موبائل پر جانچتے وقت تصویر کی اصل فائل استعمال کریں، اسکرین شاٹ نہیں۔ اسکرین شاٹ میں اصل تصویر کا میٹا ڈیٹا نہیں ہوتا، صرف اسکرین کی معلومات ہوتی ہیں۔</p>\n<h2 id=\"metadata-viewer-summary\">مختصر خلاصہ</h2>\n<p>میٹا ڈیٹا تصویر کی چھپی ہوئی کہانی ہے: کب، کہاں اور کیسے لی گئی۔ اسے جانچنا فوٹوگرافی سیکھنے اور پرائیویسی بچانے، دونوں کے لیے مفید ہے۔</p>\n<p>عادت بنائیں: شیئر کرنے سے پہلے جانچیں، صاف کریں، پھر دوبارہ جانچیں۔ میٹا ڈیٹا کی مکمل وضاحت <a href=\"/ur/blog/exif-data-wazahat/\">EXIF ڈیٹا کی وضاحت</a> میں اور دیکھنے کے عملی مراحل <a href=\"/ur/blog/tasveer-metadata-kaise-dekhein/\">تصویر کا میٹا ڈیٹا کیسے دیکھیں</a> میں پڑھیں۔ صاف کرنے کے لیے <a href=\"/ur/tasveer-metadata-hatayein/\">میٹا ڈیٹا ہٹانے</a> کا ٹول استعمال کریں۔</p>\n";

